#### Example 3: Drift Detection Pipeline Step

```yaml
# .github/workflows/drift-detection.yml (scheduled)
name: Infrastructure Drift Detection
on:
  schedule:
    - cron: '0 6 * * *'  # Daily at 06:00 UTC

jobs:
  drift-check:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4

      - name: Export Current State
        run: terraform show -json > current-state.json

      - name: Drift Evaluation
        uses: gainwell/actions/drift-evaluator@v1
        with:
          current_state: current-state.json
          declared_state_url: ${{ vars.TERRAFORM_STATE_URL }}
          policy_library_version: ${{ vars.POLICY_LIBRARY_VERSION }}
          evidence_store_url: ${{ vars.EVIDENCE_STORE_URL }}
          incident_url: ${{ vars.SERVICENOW_API_URL }}
